"use client";

import { useEffect, useRef, useState } from "react";
import { motion, AnimatePresence, useMotionValue, useSpring } from "framer-motion";

type Team = {
  rank: number;
  teamId: number;
  teamName: string;
  captain: string;
  members: string[];
  baselineEnrolled: number;
  currentEnrolled: number;
  deltaEnrolled: number;
  deltaDeals: number;
  trend: number[];
  dealsTrend: number[];
  lastUpdated: string | null;
};

const money = (n: number) =>
  n < 0
    ? `-$${Math.round(Math.abs(n)).toLocaleString("en-US")}`
    : `$${Math.round(n).toLocaleString("en-US")}`;

const units = (n: number) => Math.round(n).toLocaleString("en-US");

const LOGO_DATA_URI = "data:image/png;base64,";
const MASCOT_DATA_URI = "data:image/png;base64,";


function CountUp({
  value,
  className,
  style,
  format = money,
}: {
  value: number;
  className?: string;
  style?: React.CSSProperties;
  format?: (n: number) => string;
}) {
  const motionVal = useMotionValue(0);
  const spring = useSpring(motionVal, { stiffness: 60, damping: 20, mass: 1 });
  const [display, setDisplay] = useState(0);

  useEffect(() => {
    motionVal.set(value);
  }, [value, motionVal]);

  useEffect(() => {
    const unsub = spring.on("change", (v) => setDisplay(v));
    return unsub;
  }, [spring]);

  return (
    <span className={className} style={style}>
      {format(display)}
    </span>
  );
}

